import XCTest

/// H2 Task 12 (item 10): behavioural acceptance of Bookmarks (sort, notes, CSV round trip), Search and Text display.
///
/// Preconditions are established here, never assumed: KJV through `ensureKJVInstalled()`, and the three bookmarks
/// through the REAL CSV import of the seeded `H2 Fixtures/h2-bookmarks.csv` (generated by
/// `iosApp/scripts/generate-files-test-fixtures.py`, seeded by the controller with
/// `seed-files-provider.sh <udid> h2-bookmarks.csv "H2 Fixtures"`). Seed notes, in creation order (createdAt):
///   A  Revelation 1:1  "H2 note: first seeded in Revelation"
///   B  Genesis 1:1     "H2 note: second seeded in Genesis"
///   C  John 3:16       "H2 note: third seeded in John"
/// so date order is A,B,C (or reversed) and Bible order is B,C,A (or reversed).
///
/// Cleanup: every test restores its own state in a teardown block (relaunch with `-resetDatabases`, which drops the
/// bookmarks and the window/workspace text settings but keeps the installed modules). CSV exports are saved to
/// `H2 Fixtures` under a unique per-run name; Files has no cheap delete, so those files stay (owned folder).
///
/// Selectors NOT measured when drafted (a miss is HARNESS discovery with the tree attached, not automatically a
/// product RED): the bookmark top-bar overflow button label, the Files save picker confirm label, the text display
/// rows and font-size slider, the search results cards and the Create-index button.
final class FeatureFlowsUITests: RealAppUITestCase {
    private static var kjvEnsured = false
    override func setUp() {
        super.setUp()
        if !Self.kjvEnsured { ensureKJVInstalled(); Self.kjvEnsured = true }
        addTeardownBlock { [self] in resetAppState() }
    }

    private let noteA = "H2 note: first seeded in Revelation"
    private let noteB = "H2 note: second seeded in Genesis"
    private let noteC = "H2 note: third seeded in John"
    private var allNotes: [String] { [noteA, noteB, noteC] }

    // MARK: shared helpers

    private func resetAppState() {
        let app = XCUIApplication()
        app.launchArguments += ["-task6ResetCrashState", "-standardTestFixture", "-resetDatabases"]
        app.launch()
        sleep(3)
        app.terminate()
    }

    private func byLabel(_ app: XCUIApplication, _ label: String) -> XCUIElement {
        app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", label)).firstMatch
    }

    private func byLabel(_ app: XCUIApplication, containing text: String) -> XCUIElement {
        app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", text)).firstMatch
    }

    private func button(_ app: XCUIApplication, _ label: String) -> XCUIElement {
        app.buttons.matching(NSPredicate(format: "label == %@", label)).firstMatch
    }

    private func tapRequired(_ app: XCUIApplication, _ target: XCUIElement, _ step: String, timeout: TimeInterval = 30) {
        harnessRequire(target.waitForExistence(timeout: timeout), app, "Missing control: \(step)")
        harnessRequire(target.isHittable && target.isEnabled, app, "Unusable control: \(step)")
        target.tap()
    }

    // MARK: bookmarks: launch, overflow, seed, read

    private func launchBookmarks() -> XCUIApplication {
        let app = launch(["-standardTestFixture", "-resetDatabases", "-openDocument", "KJV", "-openRef", "John.3.16",
                          "-featureScenario", "bookmarks"])
        harnessRequire(element(app, "debug-feature-ready").waitForExistence(timeout: 90), app, "Bookmarks debug route ready")
        // Run 1 evidence: -resetDatabases is followed by the product's first-run EXAMPLE bookmarks (Exodus, Psalms, Isaiah,
        // John 3:3 ... created at launch; ReadingAppInit), so the list is never empty. The precondition is therefore that
        // none of the seeded notes exist yet; the seeded rows are isolated from the examples with the notes search.
        harnessRequire(waitUntil(timeout: 60) { self.byLabel(app, containing: "Psalms").exists || self.byLabel(app, containing: "Exodus").exists },
                       app, "Bookmark list loaded (first-run example bookmarks)")
        harnessRequire(!noteElement(app, noteA).exists, app, "PRECONDITION: seeded notes are absent before the import")
        return app
    }

    /// The top-bar overflow of the bookmarks screen has contentDescription null; Compose iOS exposed such buttons as
    /// 'menu'/'Menu' in the prompts screen (FilesFeatureUITests). The right-most hittable top-band candidate is used.
    private func openOverflow(_ app: XCUIApplication) {
        let candidates = { () -> [XCUIElement] in
            app.buttons.matching(NSPredicate(format: "label IN {'menu','Menu','More options','More'}"))
                .allElementsBoundByIndex.filter { $0.isHittable && $0.frame.minY < 220 }
        }
        harnessRequire(waitUntil(timeout: 20) { !candidates().isEmpty }, app, "HARNESS: bookmarks overflow button")
        guard let menu = candidates().max(by: { $0.frame.midX < $1.frame.midX }) else { return }
        menu.tap()
    }

    private func menuItem(_ app: XCUIApplication, _ label: String) {
        let item = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@ OR label BEGINSWITH %@",
                                                                       label, label + ",")).firstMatch
        harnessRequire(item.waitForExistence(timeout: 15), app, "HARNESS: overflow item '\(label)'")
        item.tap()
    }

    /// The notes search icon's contentDescription is strings.search = "Find" (strings.xml), not "Search" (run 4 evidence).
    private func findButton(_ app: XCUIApplication) -> XCUIElement {
        app.buttons.matching(NSPredicate(format: "label IN {'Find','Search'}")).firstMatch
    }

    /// Clears a text field and types `text`, verifying the read-back. Run 4 evidence: the reading search field read
    /// 'NicoNicodemudemus' / 'sstrongstrong:g3530' after the previous retype loop appended to leftovers. Every attempt clears
    /// with backspaces (value length + 5) first, types slowly (per character, 120 ms: the echo race of controller-bound
    /// Compose fields, see memory ios-compose-controller-flow-textfield-drops-first-key) and attaches the observed value.
    /// Returns true when the field holds exactly `text`.
    private func enterText(_ app: XCUIApplication, _ field: XCUIElement, _ text: String, label: String) -> Bool {
        for attempt in 0..<4 {
            field.tap()
            usleep(400_000)
            let current = field.value as? String ?? ""
            field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: current.count + 5))
            if attempt == 0 { field.typeText(text) } else { for ch in text { field.typeText(String(ch)); usleep(120_000) } }
            usleep(500_000)
            let value = field.value as? String ?? "nil"
            attach("\(label)-typed-attempt-\(attempt)", "wanted '\(text)', field value '\(value)'")
            if value == text { return true }
        }
        return false
    }

    private func noteElement(_ app: XCUIApplication, _ note: String) -> XCUIElement {
        app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS %@", note)).firstMatch
    }

    /// Imports a CSV from `H2 Fixtures` through overflow -> Import CSV -> Files picker; fails on an error dialog.
    /// The list is lazy and holds the first-run examples, so success is verified separately through the notes filter.
    private func importCsv(_ app: XCUIApplication, filename: String) {
        openOverflow(app)
        menuItem(app, "Import CSV")
        pick(app, folderName: "H2 Fixtures", filename: filename)
        harnessRequire(waitUntil(timeout: 60) { !app.buttons["Cancel"].firstMatch.exists }, app, "Files picker dismissed after \(filename)")
        sleep(3)
        let errors = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS 'errors' OR label CONTAINS 'import failed'")).firstMatch
        harnessRequire(!errors.exists, app, "CSV import of \(filename) reported errors")
    }

    private func seedBookmarks(_ app: XCUIApplication) {
        importCsv(app, filename: "h2-bookmarks.csv")
        ensureNotesShown(app)
        openSeededFilter(app)
        for note in allNotes {
            harnessRequire(noteElement(app, note).waitForExistence(timeout: 30), app, "Seeded note '\(note)' listed")
        }
        closeSeededFilter(app)
    }

    /// Notes are shown when the notes search icon exists (it is only offered with Show notes on). Otherwise toggle it.
    private func ensureNotesShown(_ app: XCUIApplication) {
        if findButton(app).waitForExistence(timeout: 5) { return }
        openOverflow(app)
        menuItem(app, "Show notes")
        harnessRequire(findButton(app).waitForExistence(timeout: 20), app, "Show notes made the notes search available")
    }

    /// Notes search for "H2 note": leaves only the three seeded rows (the lazy list also holds the examples). Search mode
    /// replaces the top bar, so sort/overflow are unavailable until `closeSeededFilter`.
    private func openSeededFilter(_ app: XCUIApplication) {
        tapRequired(app, findButton(app), "bookmarks-notes-search")
        let fields = { () -> [XCUIElement] in
            (app.textFields.allElementsBoundByIndex + app.searchFields.allElementsBoundByIndex + app.textViews.allElementsBoundByIndex)
                .filter { $0.exists && $0.isHittable && $0.frame.minY < 250 }
        }
        harnessRequire(waitUntil(timeout: 15) { !fields().isEmpty }, app, "HARNESS: notes search text field")
        guard let field = fields().first else { return }
        harnessRequire(enterText(app, field, "H2 note", label: "notes-filter"), app,
                       "Notes search field holds exactly 'H2 note' (is '\(field.value as? String ?? "nil")')")
        // Run 5 evidence: the open keyboard covered the lower third of the list (third row cut off, "found 2"). Submit via the
        // keyboard's search key to dismiss it; the filter stays applied.
        let key = app.keyboards.buttons.matching(NSPredicate(format: "label IN {'search','Search','return','Return'}")).firstMatch
        if key.waitForExistence(timeout: 5) { key.tap() }
        _ = waitUntil(timeout: 10) { app.keyboards.count == 0 }
    }

    private func closeSeededFilter(_ app: XCUIApplication) {
        let close = app.buttons.matching(NSPredicate(format: "label IN {'Close search','Close','Back','Navigate up','Clear'}"))
            .allElementsBoundByIndex.filter { $0.isHittable && $0.frame.minY < 250 }.min { $0.frame.midX < $1.frame.midX }
        harnessRequire(close != nil, app, "HARNESS: close control of the notes search bar")
        close?.tap()
        if app.keyboards.count > 0, findButton(app).waitForExistence(timeout: 10) == false { attachTree(app, "search-still-open") }
        harnessRequire(findButton(app).waitForExistence(timeout: 15) || app.buttons["Date order"].exists || app.buttons["Biblical order"].exists,
                       app, "Normal bookmarks top bar is back after closing the notes search")
    }

    /// The seeded notes in on-screen top-to-bottom order (all three must be present).
    private func noteOrder(_ app: XCUIApplication) -> [String] {
        let found = allNotes.compactMap { note -> (String, CGFloat)? in
            let element = noteElement(app, note)
            return element.exists ? (note, element.frame.minY) : nil
        }
        harnessRequire(found.count == 3, app, "All three seeded notes are listed (found \(found.count))")
        return found.sorted { $0.1 < $1.1 }.map(\.0)
    }

    /// Order after the list settled: two consecutive equal reads.
    private func settledOrder(_ app: XCUIApplication) -> [String] {
        var last = noteOrder(app)
        for _ in 0..<6 {
            usleep(700_000)
            let next = noteOrder(app)
            if next == last { return next }
            last = next
        }
        return last
    }

    // MARK: 1. bookmarks list: sort and notes

    func testBookmarksListSortAndNotes() throws {
        let app = launchBookmarks()
        defer { app.terminate() }
        seedBookmarks(app)
        shot(app, "bookmarks-seeded")

        // References: each seeded bookmark row names its verse.
        openSeededFilter(app)
        for reference in ["Genesis", "John 3:16", "Revelation"] {
            harnessRequire(byLabel(app, containing: reference).waitForExistence(timeout: 20), app, "A bookmark row names '\(reference)'")
        }
        closeSeededFilter(app)

        // Expected permutations (see the class comment).
        let dateAsc = [noteA, noteB, noteC], dateDesc = [noteC, noteB, noteA]
        let bibleAsc = [noteB, noteC, noteA], bibleDesc = [noteA, noteC, noteB]

        // The sort button's label names the CURRENT mode ("Date order" / "Biblical order"), the next tap cycles via .next():
        // never tap by the desired target label. The order of the three seeded rows is read through the notes filter (the
        // list also holds the first-run examples and is lazy); the filter replaces the top bar, so it is opened and closed
        // around each observation and the sort button is tapped on the normal bar.
        func sortButton() -> XCUIElement {
            app.buttons.matching(NSPredicate(format: "label IN {'Date order','Biblical order'}")).firstMatch
        }
        func observe() -> (label: String, order: [String]) {
            harnessRequire(sortButton().waitForExistence(timeout: 20), app, "HARNESS: sort button ('Date order' or 'Biblical order')")
            let label = sortButton().label
            openSeededFilter(app)
            let order = settledOrder(app)
            closeSeededFilter(app)
            return (label, order)
        }
        var observations: [(label: String, order: [String])] = [observe()]
        for _ in 0..<4 {
            sortButton().tap()
            usleep(1_000_000)
            observations.append(observe())
        }
        attach("sort-observations", observations.map { "\($0.label): \($0.order.map { $0.replacingOccurrences(of: "H2 note: ", with: "") })" }.joined(separator: "\n"))
        for observation in observations {
            let valid = observation.label == "Date order" ? [dateAsc, dateDesc] : [bibleAsc, bibleDesc]
            XCTAssertTrue(valid.contains(observation.order),
                          "Mode '\(observation.label)' shows an order that is not a date/Bible permutation: \(observation.order)")
        }
        let date = observations.filter { $0.label == "Date order" }.map(\.order)
        let bible = observations.filter { $0.label == "Biblical order" }.map(\.order)
        XCTAssertFalse(date.isEmpty, "Date order was reached by cycling")
        XCTAssertFalse(bible.isEmpty, "Biblical order was reached by cycling")
        XCTAssertTrue(date.contains(dateAsc) || date.contains(dateDesc), "A date-ordered list was observed")
        XCTAssertTrue(bible.contains(bibleAsc) || bible.contains(bibleDesc), "A Bible-ordered list was observed")
        XCTAssertGreaterThan(Set(observations.map(\.order)).count, 1, "Sorting changed the order at least once")

        // Notes: hide, then show again. Hidden notes: no search icon and no seeded note text anywhere; shown: filter lists the exact texts.
        openOverflow(app)
        menuItem(app, "Show notes")
        harnessRequire(waitUntil(timeout: 20) { !self.findButton(app).exists }, app, "Hiding notes removes the notes search")
        for note in allNotes { XCTAssertFalse(noteElement(app, note).exists, "Note '\(note)' hidden") }
        openOverflow(app)
        menuItem(app, "Show notes")
        harnessRequire(findButton(app).waitForExistence(timeout: 20), app, "Show notes restores the notes search")
        openSeededFilter(app)
        for note in allNotes {
            harnessRequire(noteElement(app, note).waitForExistence(timeout: 20), app, "Show notes lists the exact text '\(note)'")
        }
    }

    private func attach(_ name: String, _ text: String) {
        let attachment = XCTAttachment(string: text); attachment.name = name; attachment.lifetime = .keepAlways; add(attachment)
    }

    // MARK: 4. CSV round trip

    /// Export dialog: persisted column selection is part of the flow, so "Select all" is applied (notes + id included).
    private func exportCsv(_ app: XCUIApplication, stem: String) {
        openOverflow(app)
        menuItem(app, "Export CSV")
        harnessRequire(byLabel(app, "Select CSV Columns").waitForExistence(timeout: 20), app, "CSV column selection dialog")
        // Run 5 evidence: the dialog offers "Select none" when every column is already checked and "Select all" otherwise.
        // Either way all columns must end up selected (notes + id included).
        let selectAll = button(app, "Select all")
        if selectAll.waitForExistence(timeout: 5) { selectAll.tap() }
        harnessRequire(button(app, "Select none").waitForExistence(timeout: 10), app, "All CSV columns are selected ('Select none' offered)")
        tapRequired(app, button(app, "OK"), "csv-columns-ok")
        let confirm = app.navigationBars["FullDocumentManagerViewControllerNavigationBar"].buttons
            .matching(NSPredicate(format: "label IN {'Save','Move'}")).firstMatch
        harnessRequire(confirm.waitForExistence(timeout: 30), app, "Files save picker (Save/Move)")
        local(app)
        folder(app, "H2 Fixtures")
        let field = app.textFields.allElementsBoundByIndex.first { $0.isHittable }
        harnessRequire(field != nil, app, "Files save picker filename field")
        guard let field else { return }
        field.tap()
        let old = field.value as? String ?? ""
        field.typeText(String(repeating: XCUIKeyboardKey.delete.rawValue, count: old.count) + stem)
        harnessRequire((field.value as? String) == stem, app, "Save picker stem is '\(stem)' (is '\(field.value as? String ?? "nil")')")
        tapRequired(app, confirm, "files-save-confirm")
        harnessRequire(waitUntil(timeout: 30) { !confirm.exists }, app, "Save picker dismissed")
        sleep(3)
        XCTAssertFalse(byLabel(app, containing: "export failed").exists, "CSV export reported a failure")
        harnessRequire(findButton(app).waitForExistence(timeout: 30), app, "Bookmark list after export")
    }

    /// Select all rows (long-press one, tap the others), delete with the confirmation, require the empty state.
    private func deleteAllBookmarks(_ app: XCUIApplication) {
        openSeededFilter(app) // only the three seeded rows (the first-run examples are untouched and stay)
        let first = noteElement(app, noteA)
        harnessRequire(first.waitForExistence(timeout: 20) && first.isHittable, app, "Row to long-press")
        first.press(forDuration: 1.2)
        let delete = button(app, "Delete")
        harnessRequire(delete.waitForExistence(timeout: 15), app, "Selection mode shows Delete after long-press")
        for note in [noteB, noteC] {
            let row = noteElement(app, note)
            harnessRequire(row.exists && row.isHittable, app, "Row '\(note)' selectable")
            row.tap()
        }
        shot(app, "bookmarks-three-selected")
        tapRequired(app, delete, "bookmark-delete")
        tapRequired(app, button(app, "Yes"), "bookmark-delete-confirm")
        harnessRequire(byLabel(app, "No items to display").waitForExistence(timeout: 30), app, "ZERO seeded bookmarks after delete (empty filtered state)")
        for note in allNotes { XCTAssertFalse(noteElement(app, note).exists, "Note '\(note)' gone after delete") }
        closeSeededFilter(app)
    }

    func testBookmarkCsvRoundTrip() throws {
        let app = launchBookmarks()
        defer { app.terminate() }
        seedBookmarks(app)
        let stem = "h2-bookmarks-roundtrip-\(UUID().uuidString.prefix(8))"
        exportCsv(app, stem: stem)
        deleteAllBookmarks(app)
        // Empty-store import: recreation, not the update-existing path (the store is proven empty above).
        importCsv(app, filename: stem)
        ensureNotesShown(app)
        openSeededFilter(app)
        for note in allNotes {
            harnessRequire(noteElement(app, note).waitForExistence(timeout: 30), app, "Round trip restored the note '\(note)'")
        }
        for reference in ["Genesis", "John 3:16", "Revelation"] {
            harnessRequire(byLabel(app, containing: reference).exists, app, "Round trip restored the '\(reference)' bookmark")
        }
        XCTAssertEqual(Set(noteOrder(app)), Set(allNotes))
        shot(app, "bookmarks-after-roundtrip")
    }

    // MARK: 2. search

    private func launchReadingAtGenesis() -> XCUIApplication {
        // Run 1 evidence: in iPhone portrait the toolbar fits only Bible/Commentary/Strong's and More options holds just
        // Night mode, Workspaces, Window pinning, All text options: no Find (PRODUCT? suspect, see report). Like
        // ReadingUITests.testToolbarActionsOpenTheirDestinations the iPhone runs search in landscape, where Find fits.
        if !isPad {
            let device = XCUIDevice.shared
            addTeardownBlock { device.orientation = .portrait }
            device.orientation = .landscapeLeft
        }
        let app = launch(["-standardTestFixture", "-resetDatabases", "-openDocument", "KJV", "-openRef", "Gen.1.1"])
        harnessRequire(element(app, "reading-host").waitForExistence(timeout: 90), app, "Reading host")
        let genesisShown = app.webViews.staticTexts.matching(NSPredicate(format: "label CONTAINS 'In the beginning'")).firstMatch
        harnessRequire(genesisShown.waitForExistence(timeout: 60), app, "PRECONDITION: Genesis 1 is displayed")
        harnessRequire(!app.webViews.staticTexts.matching(NSPredicate(format: "label == 'Nicodemus'")).firstMatch.exists, app,
                       "PRECONDITION: John 3 is NOT displayed before the search")
        return app
    }

    /// Reading toolbar 'Find'; on narrow phones the action is in 'More options'.
    private func openFind(_ app: XCUIApplication) {
        let find = byLabel(app, "Find")
        if find.waitForExistence(timeout: 8) && find.isHittable {
            find.tap()
        } else {
            tapRequired(app, button(app, "More options"), "more-options")
            let item = app.descendants(matching: .any).matching(NSPredicate(format: "label == 'Find' OR label == 'Search'")).firstMatch
            harnessRequire(item.waitForExistence(timeout: 10), app, "Find/Search in the overflow")
            item.tap()
        }
        harnessRequire(element(app, "reading-search-field").waitForExistence(timeout: 20), app, "Reading search field")
    }

    /// Result cards: a verse reference label ("John 3:1"); distinct labels, ignoring the reading chrome.
    private func resultReferences(_ app: XCUIApplication) -> [String] {
        let cards = app.descendants(matching: .any).matching(NSPredicate(format:
            "label MATCHES %@", #"^([1-3] )?[A-Za-z]+( [A-Za-z]+)* [0-9]+:[0-9]+.*"#))
        return Array(Set(cards.allElementsBoundByIndex.map(\.label))).sorted()
    }

    /// Types the query, submits, handles the real "An index is required" flow (Create) and waits for result cards.
    @discardableResult
    private func runSearch(_ app: XCUIApplication, query: String, expectFieldDefect: Bool = false) -> Bool {
        openFind(app)
        let field = element(app, "reading-search-field")
        // Run 3/4 evidence: the field dropped or duplicated characters (see enterText). If this still fails after the
        // clear-and-slow retries the reading SearchField mangles input (PRODUCT? suspect, evidence in the attachments).
        let failure = "PRODUCT: Find field mangles input (ReadingSearchField, ReadingToolbar.kt, R3-owned): wanted '\(query)', see the reading-search-typed-attempt attachments"
        var typed = false
        if expectFieldDefect {
            // R3 product defect, ruled not fixed here: expected failure (non-strict, so a fixed field passes too). The block holds
            // ONLY the typing oracle; everything after it asserts normally.
            let options = XCTExpectedFailure.Options()
            options.isStrict = false
            XCTExpectFailure("R3 product defect: ReadingSearchField mangles typed input (ReadingToolbar.kt)", options: options) {
                typed = enterText(app, field, query, label: "reading-search")
                XCTAssertTrue(typed, failure)
            }
            if !typed {
                print("FeatureFlowsUITests: Find field is mangling input (known R3 defect), '\(query)' not exact; ending the case before the result assertions")
                return false
            }
        } else {
            typed = enterText(app, field, query, label: "reading-search")
            harnessRequire(typed, app, failure + ", is '\(field.value as? String ?? "nil")'")
        }
        field.typeText("\n")
        let deadline = Date().addingTimeInterval(180) // measured: the Nicodemus run incl. index creation took 53 s
        var indexTaps = 0
        var lastResubmit = Date()
        while Date() < deadline {
            if !resultReferences(app).isEmpty { return true }
            // A finished search with no matches shows "0 verses in 1 translations": fail fast, do not wait for cards.
            let none = app.descendants(matching: .any).matching(NSPredicate(format: "label BEGINSWITH '0 verses'")).firstMatch
            harnessRequire(!none.exists, app, "Search '\(query)' returned 0 verses (query accepted but nothing matched)")
            let create = app.buttons.matching(NSPredicate(format: "label == 'Create' OR label == 'Rebuild index'")).firstMatch
            if create.exists && create.isHittable && indexTaps < 3 {
                attachTree(app, "search-index-required")
                create.tap(); indexTaps += 1
                lastResubmit = Date()
            } else if indexTaps > 0, Date().timeIntervalSince(lastResubmit) > 45, field.exists, create.exists == false {
                // Index finished but the form is back: submit again.
                field.tap(); field.typeText("\n"); lastResubmit = Date()
            }
            sleep(2)
        }
        harnessRequire(false, app, "Search '\(query)' produced result cards within 3 minutes (index taps: \(indexTaps))")
        return false
    }

    func testSearchResultsAndStrongs() throws {
        let app = launchReadingAtGenesis()
        defer { app.terminate() }
        runSearch(app, query: "Nicodemus")
        let references = resultReferences(app)
        attach("nicodemus-results", references.joined(separator: "\n"))
        shot(app, "search-results-nicodemus")
        XCTAssertGreaterThan(references.count, 0, "Nicodemus search lists results")
        let john3 = app.descendants(matching: .any).matching(NSPredicate(format: "label BEGINSWITH 'John 3:'")).firstMatch
        harnessRequire(john3.waitForExistence(timeout: 20), app, "A result in John 3 (results: \(references))")
        john3.tap()
        harnessRequire(john3Shown(app, timeout: 90), app, "Tapping the John 3 result opens John 3 (Nicodemus phrase in the web view)")
    }

    /// Run 1 evidence: the KJV provisioned from `H2 Fixtures/h2-kjv.zip` is "King James Version (1769) with Strongs Numbers and
    /// Morphology", so a Strong's fixture DOES exist and this case is not opt-in. Query syntax `strong:g3530` (help_search_bible).
    func testStrongsSearch() throws {
        let app = launchReadingAtGenesis()
        defer { app.terminate() }
        guard runSearch(app, query: "strong:g3530", expectFieldDefect: true) else { return }
        XCTAssertFalse(resultReferences(app).isEmpty, "Strong's G3530 (Nicodemus) returns results")
        let john3 = app.descendants(matching: .any).matching(NSPredicate(format: "label BEGINSWITH 'John 3:'")).firstMatch
        XCTAssertTrue(john3.waitForExistence(timeout: 20), "G3530 result in John 3")
    }

    // MARK: 3. text display

    private struct PhraseMetrics { let widths: [CGFloat]; let heights: [CGFloat]; let top: CGFloat }

    /// The same WebKit phrases every time: the elements between the "16" and "17" verse numbers of John 3:16 must read
    /// For / God / so / loved / the world (KJV phrase split, see AppUITests.testJohn316PhraseLabels). Frames of exactly
    /// those elements are compared, never a single node and never whole-document geometry.
    private func verse16Metrics(_ app: XCUIApplication) -> PhraseMetrics? {
        // ONE accessibility snapshot of the web view (run 6: 800 per-element queries made one measurement take tens of seconds).
        guard let root = try? app.webViews.firstMatch.snapshot() else { return nil }
        var texts: [(label: String, frame: CGRect)] = []
        func walk(_ node: XCUIElementSnapshot) {
            if node.elementType == .staticText { texts.append((node.label, node.frame)) }
            node.children.forEach(walk)
        }
        walk(root)
        let labels = texts.map(\.label)
        // Run 9 (iPad): the whole chapter stack (John 1, 2, 3) is in the tree, so the FIRST "16" is John 1:16 and the old
        // first-match guard never found John 3:16. Every "16" is tried; the one followed by the KJV phrase split wins.
        var segment: [Int] = []
        for start in labels.indices where labels[start] == "16" {
            guard let end = labels[(start + 1)...].firstIndex(of: "17") else { continue }
            // Run 1 evidence: the KJV with Strong's emits a "\u{00B6}" element before "For" and wraps lines, so the pilcrow is skipped.
            let candidate = (start + 1..<end).filter { labels[$0] != "\u{00B6}" }
            if candidate.count >= 5, candidate.prefix(5).map({ labels[$0] }) == ["For", "God", "so", "loved", "the world"] {
                segment = candidate
                break
            }
        }
        guard !segment.isEmpty else { return nil }
        // Single-word elements only: "the world" can be stretched by justification, a word cannot.
        let frames = segment.prefix(4).map { texts[$0].frame }
        guard frames.allSatisfy({ !$0.isEmpty }) else { return nil }
        return PhraseMetrics(widths: frames.map(\.width), heights: frames.map(\.height), top: frames[0].minY)
    }

    /// The toolbar title as (chapter, verse) when it reads "John C:V" (top strip only, so web view headings are not hit).
    private func readingTitlePosition(_ app: XCUIApplication) -> (chapter: Int, verse: Int)? {
        let titles = app.staticTexts.matching(NSPredicate(format: "label MATCHES 'John [0-9]+:[0-9]+'")).allElementsBoundByIndex
        guard let title = titles.first(where: { $0.frame.minY < 160 && $0.frame.height > 0 }) else { return nil }
        let parts = title.label.dropFirst(5).split(separator: ":").compactMap { Int($0) }
        return parts.count == 2 ? (parts[0], parts[1]) : nil
    }

    /// Settled: two reads 1 s apart with identical widths/heights.
    private func settledVerse16(_ app: XCUIApplication, _ step: String) -> PhraseMetrics {
        var previous: PhraseMetrics?
        var result: PhraseMetrics?
        _ = waitUntil(timeout: 60) {
            guard let now = self.verse16Metrics(app) else {
                previous = nil
                return false
            }
            defer { previous = now }
            if let previous, previous.widths == now.widths, previous.heights == now.heights { result = now; return true }
            usleep(1_000_000)
            return false
        }
        if result == nil {
            let title = readingTitlePosition(app).map { "John \($0.chapter):\($0.verse)" } ?? "unreadable"
            attach("verse16-missing", "toolbar title after \(step): \(title)")
        }
        harnessRequire(result != nil, app, "John 3:16 not in view after \(step) (saved position lost)")
        return result ?? PhraseMetrics(widths: [], heights: [], top: 0)
    }

    private func openTextOptions(_ app: XCUIApplication) {
        tapRequired(app, button(app, "More options"), "more-options")
        let item = app.descendants(matching: .any).matching(NSPredicate(format: "label BEGINSWITH 'All text options'")).firstMatch
        harnessRequire(item.waitForExistence(timeout: 15), app, "'All text options' in More options")
        item.tap()
        harnessRequire(byLabel(app, containing: "Font size").waitForExistence(timeout: 30), app, "Text display screen lists Font size")
    }

    /// Leaves the text display screen the way the user does (Back), returning to the reading page.
    private func closeTextOptions(_ app: XCUIApplication) {
        tapRequired(app, app.buttons.matching(NSPredicate(format: "label IN {'Back','Navigate up'}")).firstMatch, "text-options-back")
        harnessRequire(element(app, "reading-host").waitForExistence(timeout: 30), app, "Reading host after text options")
    }

    private func redLettersSwitch(_ app: XCUIApplication) -> XCUIElement {
        let toggle = app.switches.matching(NSPredicate(format: "label CONTAINS[c] 'red letter' OR label CONTAINS[c] 'words of Christ'")).firstMatch
        for _ in 0..<12 where !(toggle.exists && toggle.isHittable) { nudgeList(app, up: true) }
        harnessRequire(toggle.exists && toggle.isHittable, app, "Red letter switch reachable in the text display list")
        return toggle
    }

    private func fontSizeRow(_ app: XCUIApplication) -> XCUIElement {
        app.descendants(matching: .any).matching(NSPredicate(format: "label BEGINSWITH 'Font size'")).firstMatch
    }

    /// The numeric readout of the font size editor ("NN pt" or "NN %"); used as the oracle while bisecting the slider.
    private func fontReadout(_ app: XCUIApplication) -> Int? {
        let readout = app.staticTexts.matching(NSPredicate(format: "label MATCHES %@", #"^\d+ ?(pt|%)$"#)).firstMatch
        guard readout.exists else { return nil }
        return Int(readout.label.filter(\.isNumber))
    }

    /// Run 6 evidence: the font size control is an `Other` element whose value is "16.0" (not an XCUIElement slider), so
    /// `adjust(toNormalizedSliderPosition:)` throws. Found by value pattern (a cheap predicate query), widest first.
    private func fontSlider(_ app: XCUIApplication) -> XCUIElement? {
        let candidates = app.otherElements.matching(NSPredicate(format: "value MATCHES %@", #"^[0-9]+(\.[0-9]+)?$"#))
        return candidates.allElementsBoundByIndex.filter { $0.frame.width > 200 && $0.frame.height < 80 }.first
    }

    private func sliderValue(_ slider: XCUIElement) -> Double? {
        (slider.value as? Double) ?? (slider.value as? String).flatMap(Double.init)
    }

    /// Opens the font size sheet and drags the thumb to current + delta, correcting from the element's value (range 1...60 from
    /// TextDisplaySettingsServiceImpl; thumb centre at left + 24 + (v - 1) / 59 * (width - 48), the geometry measured for the
    /// Speak slider). Confirms with OK. Returns (old, new).
    private func raiseFontSize(_ app: XCUIApplication, by delta: Int) -> (Int, Int) {
        tapRequired(app, fontSizeRow(app), "font-size-row")
        harnessRequire(waitUntil(timeout: 20) { self.fontSlider(app) != nil }, app, "HARNESS: font size sheet shows the slider element")
        guard let slider = fontSlider(app), let old = sliderValue(slider) else { return (0, 0) }
        let target = old + Double(delta)
        let width = slider.frame.width
        func offset(_ value: Double) -> CGFloat { CGFloat((24 + (value - 1) / 59 * (Double(width) - 48)) / Double(width)) }
        var current = old
        for _ in 0..<6 where current != target {
            let start = slider.coordinate(withNormalizedOffset: CGVector(dx: offset(current), dy: 0.5))
            let end = slider.coordinate(withNormalizedOffset: CGVector(dx: offset(target), dy: 0.5))
            start.press(forDuration: 0.3, thenDragTo: end)
            usleep(800_000)
            current = sliderValue(slider) ?? current
        }
        attach("font-slider", "old \(old) target \(target) reached \(current) width \(width)")
        shot(app, "font-size-sheet")
        harnessRequire(current == target, app, "HARNESS: font slider reached \(target) from \(old) (is \(current))")
        tapRequired(app, button(app, "OK"), "font-size-ok")
        return (Int(old), Int(current))
    }

    /// (1) turning red letters OFF only must not change the text metrics of the tracked phrases (it recolours words of
    /// Christ, it does not resize), (2) a font size increase of +2 must grow the same phrases. XCTest cannot read WKWebView
    /// computed styles, so the evidence is the AX frames of identical phrases at settled states; the red-letter step is
    /// the control that separates "geometry changed because of config churn" from "because of the font multiplier".
    func testTextDisplayEditAppliesToReading() throws {
        var app = launch(["-standardTestFixture", "-resetDatabases", "-openDocument", "KJV", "-openRef", "John.3.16"])
        defer { app.terminate() }
        harnessRequire(element(app, "reading-host").waitForExistence(timeout: 90), app, "Reading host")
        let baseline = settledVerse16(app, "baseline")
        attach("baseline", "\(baseline)")
        shot(app, "text-display-baseline")

        // Red letters off.
        openTextOptions(app)
        let red = redLettersSwitch(app)
        // Run 4: the screenshot showed the switch flipped while `isSelected` did not change; the AX value ("1"/"0") is the oracle.
        // Run 5: value is '' and isSelected false before AND after although the screenshot shows the switch flipped, so the
        // state is not exposed through AX. Oracle: the element's own pixels (knob moves) differ before/after, plus the
        // later reading-page effect. Starting state ON is the baseline screenshot (red words of Christ).
        let redPixels = { red.screenshot().pngRepresentation }
        let redBefore = redPixels()
        attach("red-before", "label=\(red.label) value=\(red.value as? String ?? "nil") selected=\(red.isSelected) bytes=\(redBefore.count)")
        red.coordinate(withNormalizedOffset: CGVector(dx: 0.3, dy: 0.5)).tap()
        harnessRequire(waitUntil(timeout: 10) { redPixels() != redBefore }, app, "Red letter switch toggled (element pixels unchanged after the tap)")
        sleep(1)
        shot(app, "text-display-red-letters-toggled")
        closeTextOptions(app)
        let afterRed = settledVerse16(app, "after red letters")
        XCTAssertEqual(afterRed.widths.count, baseline.widths.count)
        for (before, after) in zip(baseline.widths + baseline.heights, afterRed.widths + afterRed.heights) {
            XCTAssertEqual(before, after, accuracy: 1.5, "Red-letter toggle alone must not resize the tracked phrases")
        }

        // Font size +2.
        openTextOptions(app)
        let (old, new) = raiseFontSize(app, by: 2)
        XCTAssertEqual(new, old + 2, "Font size editor moved by +2")
        closeTextOptions(app)
        let afterFont = settledVerse16(app, "after font size")
        let grown = zip(afterRed.widths, afterFont.widths).map { $1 / $0 }
        attach("growth", "font \(old) -> \(new); width ratios \(grown); heights \(afterRed.heights) -> \(afterFont.heights)")
        shot(app, "text-display-font-increased")
        XCTAssertTrue(grown.allSatisfy { $0 > 1.03 }, "Every tracked phrase widened with font size +2 (ratios \(grown))")
        XCTAssertGreaterThan(afterFont.heights.reduce(0, +), afterRed.heights.reduce(0, +), "Phrase heights grew")

        // The setting persisted to the reading page across a relaunch (no -resetDatabases): same grown metrics.
        sendToBackground(app)
        app.terminate()
        app = launch(["-openDocument", "KJV", "-openRef", "John.3.16"])
        harnessRequire(element(app, "reading-host").waitForExistence(timeout: 90), app, "Reading host after relaunch")
        let relaunched = settledVerse16(app, "after relaunch")
        for (a, b) in zip(afterFont.widths, relaunched.widths) {
            XCTAssertEqual(a, b, accuracy: 1.5, "Font size persisted across a relaunch")
        }
    }
}
